"""Report every finite positional condition after independent native replay."""
import json,csv
import numpy as np
from .finite_positional_common import OUT,sha,source_guard

def main():
    p=json.loads((OUT/'protocol.json').read_text());source_guard(p);r=json.loads((OUT/'statistics.json').read_text());a=json.loads((OUT/'evidence_audit.json').read_text());assert a['passed'] and a['producer_manifest_sha256']==sha(OUT/'manifest.json');rows=r['rows'];pairs=[]
    for b in p['field_bounds']:
        for k in p['spatial_bits']:
            for t in p['parallel_samples']:
                one=next(x for x in rows if x['field_bound']==b and x['pbits_per_scalar']==1 and x['samples']==k*t);multi=next(x for x in rows if x['field_bound']==b and x['pbits_per_scalar']==k and x['samples']==t);pairs.append({'bound':b,'K':k,'positional_T':t,'single_T':k*t,'updates_per_scalar':k*t,'single_rmse':one['rmse'],'positional_rmse':multi['rmse'],'positional_over_single_MSE':multi['mse']/one['mse'],'single_theory_bias_squared':one['theory_squared_bias'],'positional_theory_bias_squared':multi['theory_squared_bias']})
    with (OUT/'equal_updates.csv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=list(pairs[0]));w.writeheader();w.writerows(pairs)
    lines=['# Finite-bias positional versus temporal p-bits in official THRML','','This is an internal scalar baseline, not an asserted Extropic weight architecture. Every stochastic state is sampled by the pinned official THRML unary Gibbs implementation. One free node encodes each normalized target as its requested stationary probability, with a finite 8-bit control field. The positional baseline quantizes the target to K bits, then programs K free nodes to fields +/-B according to those bits. All endpoints remain free and imperfect. No infinite field or clamped exact bit is substituted.','','## Frozen protocol and checks','',f'257 endpoint-inclusive targets; 1,000 trials each (five seeds x 200); field bounds B=4 primary and B=2 secondary; K=2/4/8; positional T=1/4/16/64. Every one-node budget needed for equal K*T updates is included. Prefix counts preserve all outcomes. One warmup sweep produces the first observed state; total sweeps equal samples. {r["native_node_updates"]:,} production node updates and {a["independent_native_node_updates"]:,} independent replay updates. All {a["public_counts_exact"]:,} saved count elements match independent public-API replay; all {a["analytic_and_empirical_rows_checked"]} rows pass independent raw-moment checks. Original frozen six-sigma aggregate MSE gate: **{r["passed"]}**, max |z|={r["max_abs_mse_z"]:.3f}. No hardware clock or energy is measured.','','## Equal stochastic node-update counts','','| B | K | Positional T | Single T | Single RMSE | Positional RMSE | Positional/single MSE |','|---:|---:|---:|---:|---:|---:|---:|']
    for x in pairs:lines.append(f'| {x["bound"]} | {x["K"]} | {x["positional_T"]} | {x["single_T"]} | {x["single_rmse"]:.6f} | {x["positional_rmse"]:.6f} | {x["positional_over_single_MSE"]:.4f} |')
    lines+=['','## Interpretation and limits','','The one-node design trades spatial node count for temporal precision; it does not win every scalar error comparison. The positional code has quantization bias and a finite-field bit-error floor. Increasing T only removes sampling variance, not either method\'s fixed approximation bias. These formulas include those biases rather than comparing only sampling variance. Counts from K near-deterministic nodes do not have the same estimator distribution as K replicas at p=w.','','At equal updates, the one-node method runs K times as many parallel sample rounds as the positional method, assuming all devices update simultaneously. At equal sample rounds the positional method uses K times as many nodes and updates. These are logical counters, not measured latency, power or area. A positional code uses K programmed binary selectors per scalar plus shared +/-B levels; SPW uses eight programmed control-code bits per scalar plus shared finite-field mapping, in addition to its one dynamic state. Physical control circuits, retention, calibration, accumulator/readout, signed-weight range metadata and arithmetic remain unmeasured. No total-memory or systems advantage follows from node count alone.','','Uniform scalar reconstruction does not establish neural accuracy or a matched-quality systems crossover. This study does not use neural text or choose a new neural candidate. Prior failed quality gates and earlier numerical replay failures remain unchanged. The direct probability representation works in the official simulator; whether it is preferable depends on application tolerance and the physical controller/sampling regime.','','Reproduce after immutable preparation: `.venv/bin/python -m research.thrml_spw.gpu_environment -- .venv-thrml-gpu/bin/python -m research.thrml_spw.verify_finite_positional`; generate this report with `.venv-thrml/bin/python -m research.thrml_spw.finite_positional_report`. The producer refuses to overwrite raw evidence. Broad research goal active.']
    report=OUT.parent/'FINITE_POSITIONAL_REPORT.md';report.write_text('\n'.join(lines)+'\n')
    import matplotlib;matplotlib.use('Agg');import matplotlib.pyplot as plt
    fig,axes=plt.subplots(1,2,figsize=(11,4.5),layout='constrained')
    for ax,b in zip(axes,p['field_bounds']):
        for k in [1]+p['spatial_bits']:
            rr=[x for x in rows if x['field_bound']==b and x['pbits_per_scalar']==k];ax.loglog([x['node_updates_per_scalar_trial'] for x in rr],[x['rmse'] for x in rr],'o-',label='one p-bit, 8-bit control' if k==1 else f'{k} positional p-bits')
        ax.set(xlabel='Stochastic node updates per scalar/trial',ylabel='Scalar reconstruction RMSE',title=f'Finite field B={b}');ax.legend(fontsize=8)
    fig.savefig(OUT.parent/'finite_positional.png',dpi=180);plt.close(fig);print(report)
if __name__=='__main__':main()
